2024	static uint32_t dvp_frame_get(void)
2025	{
2026	  irqstate_t flags;
2027	  int idx;
2028	  uint32_t addr;
2029	
2030	  flags = enter_critical_section();
2031	  idx = g_ready_buf;
2032	  if (idx >= 0)
2033	    {
2034	      g_busy_buf  = idx;
2035	      g_ready_buf = -1;
2036	      addr = (uint32_t)(uintptr_t)g_camera_buf[idx];
2037	    }
2038	  else
2039	    {
2040	      addr = 0;
2041	    }
2042	
2043	  leave_critical_section(flags);
2044	  return addr;
2045	}
2046	
2047	static void dvp_frame_put(void)
2048	{
2049	  irqstate_t flags;
2050	
2051	  flags = enter_critical_section();
2052	  g_busy_buf = -1;
2053	  leave_critical_section(flags);
2054	}
