/****************************************************************************
 * Name: bk7258_camera_uvhist
 *
 * Description:
 *   Diagnostic command: sample UYVY chrominance (U,V) and luminance (Y)
 *   from a live camera frame and print ASCII histograms.
 *
 *   Sampling grid: 640x480 UYVY, every 4th group horizontally (80 cols),
 *   every 8th row vertically (60 rows) = 4800 samples per frame.
 *   Each sample reads one 32-bit word [U Y0 V Y1] from the aligned
 *   PSRAM address - no byte-at-a-time reads.
 *
 *   Purpose: measure actual UV distribution under real lighting before
 *   setting skin-tone thresholds.  GC2145 AWB shifts chrominance away
 *   from textbook Cb/Cr ranges, so blind-copied thresholds won't work.
 *
 *   Read-only: does not touch preview path, sensor config, or frame
 *   buffer contents.  ASCII output readability is the priority.
 *
 * Usage: camera uvhist [n]   (n = frame count, default 1, accumulated)
 *
 ****************************************************************************/

/* UV histogram: 16x16 buckets, indexed by high nibble of U and V.
 * Y histogram: 16 buckets, indexed by high nibble of Y.
 */

#define UVHIST_BUCKETS    16
#define UVHIST_SAMPLES_X  80   /* every 4th UYVY group across 320 */
#define UVHIST_SAMPLES_Y  60   /* every 8th row across 480 */
#define UVHIST_TOTAL      (UVHIST_SAMPLES_X * UVHIST_SAMPLES_Y)

/* Row stride in bytes: 640 pixels * 2 bytes/pixel = 1280 */

#define UYVY_ROW_STRIDE   (CAMERA_HRES * CAMERA_BPP)

/* UYVY group stride: skip 4 groups = 16 bytes between samples */

#define UYVY_GROUP_STRIDE 4
#define UYVY_SAMPLE_STRIDE (UYVY_GROUP_STRIDE * 4)  /* 16 bytes */

int bk7258_camera_uvhist(int n_frames)
{
  static uint32_t uv_hist[UVHIST_BUCKETS][UVHIST_BUCKETS];
  static uint32_t y_hist[UVHIST_BUCKETS];

  int ret;
  int captured;
  int timeout_ms;
  int row;
  int col;
  uint32_t total_samples;
  uint32_t u_sum;
  uint32_t v_sum;
  uint32_t y_sum;
  uint8_t u_min;
  uint8_t u_max;
  uint8_t v_min;
  uint8_t v_max;
  uint8_t y_min;
  uint8_t y_max;
  int peak_u;
  int peak_v;
  uint32_t peak_count;
  uint32_t max_hist;
  int i;
  int j;

  /* Density characters for ASCII histogram: 10 levels from empty to full */

  static const char density[] = " .:-=+*#%@";

  if (n_frames <= 0) n_frames = 1;

  if (!g_dvp_pins_configed)
    {
      syslog(LOG_ERR, "[uvhist] DVP pins not configured\n");
      return -ENODEV;
    }

  if (!g_framebuf_allocated)
    {
      syslog(LOG_ERR, "[uvhist] frame buffers not allocated\n");
      return -ENOMEM;
    }

  /* Zero accumulators */

  memset(uv_hist, 0, sizeof(uv_hist));
  memset(y_hist, 0, sizeof(y_hist));
  total_samples = 0;
  u_sum = 0;
  v_sum = 0;
  y_sum = 0;
  u_min = 255;
  u_max = 0;
  v_min = 255;
  v_max = 0;
  y_min = 255;
  y_max = 0;

  /* Start DVP streaming */

  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
  if (ret < 0) goto cleanup_ctrl;

  ret = dvp_irq_attach();
  if (ret < 0) goto cleanup_irq;

  g_dvp_vsync_count = 0;
  g_dvp_frame_count = 0;
  g_pingpong_count  = 0;
  g_drop_count      = 0;
  g_cur_buf         = 0;
  g_ready_buf       = -1;
  g_busy_buf        = -1;
  g_stream_active   = true;

  syslog(LOG_INFO,
         "[uvhist] start: %d frame(s), %d samples/frame\n",
         n_frames, UVHIST_TOTAL);

  captured = 0;

  while (captured < n_frames)
    {
      uint32_t frame_addr;
      const uint8_t *buf;

      timeout_ms = 5000;
      while (timeout_ms > 0)
        {
          frame_addr = dvp_frame_get();
          if (frame_addr != 0) break;
          up_udelay(1000);
          timeout_ms--;
        }

      if (frame_addr == 0)
        {
          syslog(LOG_ERR, "[uvhist] TIMEOUT waiting for frame %d/%d\n",
                 captured + 1, n_frames);
          ret = -ETIMEDOUT;
          break;
        }

      buf = (const uint8_t *)(uintptr_t)frame_addr;
      captured++;

      /* Sample the grid: 60 rows x 80 columns.
       * Each UYVY group is 4 bytes: [U Y0 V Y1].
       * We read the group as a single uint32_t and extract U/V/Y0.
       * Row stride = 1280 bytes, sample stride = 16 bytes (4 groups).
       */

      for (row = 0; row < CAMERA_VRES; row += 8)
        {
          const uint8_t *row_base = buf + row * UYVY_ROW_STRIDE;

          for (col = 0; col < UVHIST_SAMPLES_X; col++)
            {
              /* Each sample is at an aligned 4-byte offset:
               * group index = col * 4, byte offset = col * 16.
               * Read as uint32_t: byte0=U, byte1=Y0, byte2=V, byte3=Y1.
               */

              uint32_t pixel = *(const uint32_t *)(row_base + col * 16);
              uint8_t u = (uint8_t)(pixel & 0xff);
              uint8_t y = (uint8_t)((pixel >> 8) & 0xff);
              uint8_t v = (uint8_t)((pixel >> 16) & 0xff);

              int u_idx = u >> 4;  /* high nibble -> 0..15 */
              int v_idx = v >> 4;
              int y_idx = y >> 4;

              uv_hist[v_idx][u_idx]++;
              y_hist[y_idx]++;
              total_samples++;

              /* Running stats */

              u_sum += u;
              v_sum += v;
              y_sum += y;

              if (u < u_min) u_min = u;
              if (u > u_max) u_max = u;
              if (v < v_min) v_min = v;
              if (v > v_max) v_max = v;
              if (y < y_min) y_min = y;
              if (y > y_max) y_max = y;
            }
        }

      dvp_frame_put();

      /* Per-frame progress line */

      if (n_frames > 1)
        {
          syslog(LOG_INFO, "[uvhist] frame %d/%d sampled\n",
                 captured, n_frames);
        }
    }

  /* Stop streaming */

  g_stream_active = false;
  dvp_irq_detach();
  dvp_ctrl_deconfig();

  if (total_samples == 0)
    {
      printf("[uvhist] no samples collected\n");
      return ret < 0 ? ret : -EIO;
    }

  /* Find peak UV bucket */

  peak_count = 0;
  peak_u = 0;
  peak_v = 0;

  for (i = 0; i < UVHIST_BUCKETS; i++)
    {
      for (j = 0; j < UVHIST_BUCKETS; j++)
        {
          if (uv_hist[i][j] > peak_count)
            {
              peak_count = uv_hist[i][j];
              peak_v = i;
              peak_u = j;
            }
        }
    }

  /* ========== Print results ========== */

  printf("\n");
  printf("[uvhist] === UV/Y histogram (%d frame(s), %lu samples) ===\n",
         n_frames, (unsigned long)total_samples);
  printf("\n");

  /* Summary stats */

  printf("[uvhist] U(Cb): min=%3u  max=%3u  mean=%lu\n",
         u_min, u_max,
         (unsigned long)(u_sum / total_samples));
  printf("[uvhist] V(Cr): min=%3u  max=%3u  mean=%lu\n",
         v_min, v_max,
         (unsigned long)(v_sum / total_samples));
  printf("[uvhist] Y:     min=%3u  max=%3u  mean=%lu\n",
         y_min, y_max,
         (unsigned long)(y_sum / total_samples));
  printf("[uvhist] peak UV bucket: (U=0x%02X, V=0x%02X) count=%lu\n",
         (peak_u << 4) | 0x08,   /* bucket center */
         (peak_v << 4) | 0x08,
         (unsigned long)peak_count);
  printf("\n");

  /* ========== 16x16 UV histogram (ASCII art) ========== */

  printf("[uvhist] UV histogram (U=Cb horizontal, V=Cr vertical)\n");
  printf("[uvhist] bucket center = index<<4 | 0x08\n");
  printf("\n");

  /* Column header: U bucket indices */

  printf("[uvhist] V\\U ");
  for (j = 0; j < UVHIST_BUCKETS; j++)
    {
      printf(" %02x ", (j << 4) | 0x08);
    }

  printf("\n");

  /* Find max count for density scaling */

  max_hist = 0;
  for (i = 0; i < UVHIST_BUCKETS; i++)
    {
      for (j = 0; j < UVHIST_BUCKETS; j++)
        {
          if (uv_hist[i][j] > max_hist)
            {
              max_hist = uv_hist[i][j];
            }
        }
    }

  /* Print rows (V axis, top = V=0x00, bottom = V=0xf0) */

  for (i = 0; i < UVHIST_BUCKETS; i++)
    {
      printf("[uvhist] %02X  ", (i << 4) | 0x08);

      for (j = 0; j < UVHIST_BUCKETS; j++)
        {
          uint32_t count = uv_hist[i][j];

          if (count == 0)
            {
              printf("  . ");
            }
          else
            {
              /* Map count to density level 1..9 */

              int level;
              if (max_hist == 0)
                {
                  level = 1;
                }
              else
                {
                  level = (int)((uint64_t)count * 9 / max_hist);
                  if (level < 1) level = 1;
                  if (level > 9) level = 9;
                }

              printf("  %c ", density[level]);
            }
        }

      printf("\n");
    }

  printf("\n");

  /* ========== Y histogram (ASCII bar chart) ========== */

  printf("[uvhist] Y histogram (luminance, 16 buckets)\n");
  printf("\n");

  /* Find max Y count for bar scaling */

  max_hist = 0;
  for (i = 0; i < UVHIST_BUCKETS; i++)
    {
      if (y_hist[i] > max_hist)
        {
          max_hist = y_hist[i];
        }
    }

  for (i = 0; i < UVHIST_BUCKETS; i++)
    {
      int bar_len;

      printf("[uvhist] 0x%02X [%5lu] ",
             (i << 4) | 0x08,
             (unsigned long)y_hist[i]);

      /* Scale bar to 40 chars max */

      if (max_hist > 0)
        {
          bar_len = (int)((uint64_t)y_hist[i] * 40 / max_hist);
        }
      else
        {
          bar_len = 0;
        }

      for (j = 0; j < bar_len; j++)
        {
          printf("#");
        }

      printf("\n");
    }

  printf("\n");

  return ret < 0 ? ret : 0;

cleanup_irq:
  dvp_irq_detach();
cleanup_ctrl:
  dvp_ctrl_deconfig();
  return ret;
}

