/****************************************************************************
 * UYVY -> RGB565 scaled conversion
 *
 * GC2145 (reg 0x84 = 0x02) + BK7258 YUV_BUF (CTRL FMT=00) combination
 * produces UYVY byte order in PSRAM, verified by camera dump:
 *   byte0=U (~0x80 neutral), byte1=Y (luminance), byte2=V, byte3=Y
 *
 * UYVY 4-byte layout per 2 pixels:
 *   [U  Y0  V  Y1]
 *    b0  b1  b2  b3
 *
 * Source byte offset for pixel sx = sx * 2.
 *   even sx: Y=b0, U=b1, V=b3  (from p = row + sx*2)
 *   odd  sx: Y=b2, U=b1, V=b3  (from p = row + sx*2, same pair)
 * Simplified: always p = row + (sx & ~1)*2, then:
 *   Y = p[1 + (sx&1)*2],  U = p[0],  V = p[2]
 ****************************************************************************/

static void uyvy_to_rgb565_scaled(const uint8_t *src,
                                  uint8_t *dst,
                                  int src_w, int src_h,
                                  int dst_w, int dst_h)
{
  int sx, sy, dx, dy;
  uint8_t *out = dst;
  int scale_x = src_w / dst_w;
  int scale_y = src_h / dst_h;

  for (dy = 0; dy < dst_h; dy++)
    {
      sy = dy * scale_y;
      const uint8_t *row = src + sy * src_w * 2;

      for (dx = 0; dx < dst_w; dx++)
        {
          uint8_t y0;
          int cb_i, cr_i, r, g, b;
          uint16_t rgb;
          int pos;

          sx = dx * scale_x;

          /* UYVY: pair pointer = start of 4-byte group */

          const uint8_t *p = row + (sx & ~1) * 2;
          /* VYUY: pair pointer = start of 4-byte group.
           *
           * Byte order is V Y0 U Y1, i.e. Cr comes first, NOT Cb.
           * Established 2026-08-21 by pointing the sensor at a full-screen
           * pure red and then a pure blue phone display:
           *   red  -> byte0 mean 230 (high), byte2 mean 101 (low)
           *   blue -> byte0 mean 127,        byte2 mean 219 (high)
           * Theory: red is Cb 85 / Cr 255, blue is Cb 255 / Cr 107.  Both
           * tests independently put Cr at byte0 and Cb at byte2.  A face
           * confirms it a third time: byte2 114 < 128 < byte0 144, which is
           * the skin invariant Cb < 128 < Cr.
           *
           * The earlier "UYVY verified by memory dump" claim was invalid:
           * that dump was taken on a near-grey scene where Cb ~ Cr ~ 128,
           * so the two are indistinguishable.  A dump can show WHICH bytes
           * carry chroma, but not which of them is which.
           */

          const uint8_t *p = row + (sx & ~1) * 2;

          y0   = p[1 + (sx & 1) * 2];     /* Y0=p[1], Y1=p[3] */
          cr_i = (int)p[0] - 128;          /* Cr (V) = byte0 */
          cb_i = (int)p[2] - 128;          /* Cb (U) = byte2 */2);
          b = (int)y0 + cb_i + (cb_i * 99 / 128);

          if (r < 0) r = 0;
          if (r > 255) r = 255;
          if (g < 0) g = 0;
          if (g > 255) g = 255;
          if (b < 0) b = 0;
          if (b > 255) b = 255;

          /* Store as big-endian RGB565 (hi byte first) to match
           * lcd_fill_rect byte order which drives this LCD correctly.
           */

          rgb = (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
          pos = (dy * dst_w + dx) * 2;
          out[pos]     = (uint8_t)(rgb >> 8);    /* hi = R[4:0] G[5:3] */
          out[pos + 1] = (uint8_t)(rgb & 0xff);  /* lo = G[2:0] B[4:0] */
        }
    }
}

