              uint8_t cr = (uint8_t)(pixel & 0xff);         /* Cr = byte0 */
              uint8_t y  = (uint8_t)((pixel >> 8) & 0xff);
              uint8_t cb = (uint8_t)((pixel >> 16) & 0xff); /* Cb = byte2 */

              total_samples++;
              frame_samples++;

              if (y >= SKIN_Y_LO && y <= SKIN_Y_HI &&
                  cb >= SKIN_CB_LO && cb <= SKIN_CB_HI &&
                  cr >= SKIN_CR_LO && cr <= SKIN_CR_HI)
                {
                  col_hist[col]++;
                  row_hist[row / 8]++;
                  total_hits++;
                  frame_hits++;
                }
            }
        }

      dvp_frame_put();

      /* Per-frame direction (n>1: print each frame for jitter).
       * pf_col[] holds the pre-frame snapshot; the delta
       * col_hist[i] - pf_col[i] is this frame's contribution.
       */

      if (n_frames > 1)
        {
          if (frame_hits < DETECT_MIN_HITS_PER_FRAME)
            {
              printf("[detect] frame %d: no target "
                     "(%d hits < %d min)\n",
                     captured, frame_hits,
                     DETECT_MIN_HITS_PER_FRAME);
            }
          else
            {
              int f_peak = 0;
              uint16_t f_peak_val = 0;

              for (i = 0; i < DETECT_SAMPLES_X; i++)
                {
                  uint16_t delta = col_hist[i] - pf_col[i];

                  if (delta > f_peak_val)
                    {
                      f_peak_val = delta;
                      f_peak = i;
                    }
                }

              int f_blob_l = f_peak;
              int f_blob_r = f_peak;
              uint16_t f_thresh = f_peak_val / 2;

              while (f_blob_l > 0 &&
                     (col_hist[f_blob_l - 1] -
                      pf_col[f_blob_l - 1]) >= f_thresh)
                {
                  f_blob_l--;
                }

              while (f_blob_r < DETECT_SAMPLES_X - 1 &&
                     (col_hist[f_blob_r + 1] -
                      pf_col[f_blob_r + 1]) >= f_thresh)
                {
                  f_blob_r++;
                }

              uint32_t f_wsum = 0;
              uint32_t f_cnt = 0;

              for (i = f_blob_l; i <= f_blob_r; i++)
                {
                  uint16_t delta = col_hist[i] - pf_col[i];

                  f_wsum += (uint32_t)delta * i;
                  f_cnt += delta;
                }

              int f_cx = f_cnt > 0 ? (int)(f_wsum / f_cnt) : f_peak;
              int f_dx = (f_cx - DETECT_SAMPLES_X / 2) * 127
                         / (DETECT_SAMPLES_X / 2);

              if (f_dx < -127) f_dx = -127;
              if (f_dx > 127)  f_dx = 127;

              printf("[detect] frame %d: dx=%+d  cx=%.1f  "
                     "blob[%d..%d]  hits=%d/%d\n",
                     captured, f_dx,
                     (float)f_wsum / (float)f_cnt,
                     f_blob_l, f_blob_r,
                     frame_hits, (int)frame_samples);
            }
        }
    }

  /* Stop streaming */

  g_stream_active = false;
  dvp_irq_detach();
  dvp_ctrl_deconfig();

  /* Minimum hit check on accumulated totals */

  if (total_hits < (uint32_t)DETECT_MIN_HITS_PER_FRAME * n_frames)
    {
      printf("\n");
      printf("[detect] no target (%lu hits < %d min)\n",
             (unsigned long)total_hits,
             (int)(DETECT_MIN_HITS_PER_FRAME * n_frames));
      return 0;
    }

  /* Find peak column in accumulated col_hist */

  peak_col = 0;
  peak_val = 0;
  for (i = 0; i < DETECT_SAMPLES_X; i++)
    {
      if (col_hist[i] > peak_val)
        {
          peak_val = col_hist[i];
          peak_col = i;
        }
    }

  /* Expand from peak: half-maximum region growing */

  blob_l = peak_col;
  blob_r = peak_col;

  while (blob_l > 0 && col_hist[blob_l - 1] >= peak_val / 2)
    {
      blob_l--;
    }

  while (blob_r < DETECT_SAMPLES_X - 1 &&
         col_hist[blob_r + 1] >= peak_val / 2)
    {
      blob_r++;
    }

  blob_width = blob_r - blob_l + 1;

  /* Weighted centroid within blob */

  blob_weighted_sum = 0;
  blob_hits = 0;
  for (i = blob_l; i <= blob_r; i++)
    {
      blob_weighted_sum += (uint32_t)col_hist[i] * i;
      blob_hits += col_hist[i];
    }

  cx = blob_hits > 0 ? (int)(blob_weighted_sum / blob_hits) : peak_col;

  /* Normalized direction: dx in [-127, +127]
   * center = DETECT_SAMPLES_X/2 = 40, scale = 40
   */

  dx = (cx - DETECT_SAMPLES_X / 2) * 127 / (DETECT_SAMPLES_X / 2);
  if (dx < -127) dx = -127;
  if (dx > 127)  dx = 127;

  confidence = total_samples > 0
    ? (float)total_hits * 100.0f / (float)total_samples
    : 0.0f;

  /* ========== Print results ========== */

  printf("\n");
  printf("[detect] %d frame(s): %lu hits / %lu samples (%.1f%%)\n",
         n_frames, (unsigned long)total_hits,
         (unsigned long)total_samples, confidence);
  printf("\n");

  /* Column histogram: density row (one char per column) */

  printf("[detect] col_hist (accumulated %d frame(s)):\n", n_frames);

  {
    uint16_t col_max = 0;

    for (i = 0; i < DETECT_SAMPLES_X; i++)
      {
        if (col_hist[i] > col_max) col_max = col_hist[i];
      }

    printf("[detect] ");
    for (i = 0; i < DETECT_SAMPLES_X; i++)
      {
        int level;

        if (col_max == 0)
          {
            level = 0;
          }
        else
          {
            level = (int)((uint32_t)col_hist[i] * 9 / col_max);
            if (level > 9) level = 9;
          }

        printf("%c", density[level]);
      }

    printf("\n");

    /* Marker row: peak='^', blob='[---]' */

    printf("[detect] ");
    for (i = 0; i < DETECT_SAMPLES_X; i++)
      {
        if (i == peak_col)
          {
            printf("^");
          }
        else if (i == blob_l)
          {
            printf("[");
          }
        else if (i == blob_r)
          {
            printf("]");
          }
        else if (i > blob_l && i < blob_r)
          {
            printf("-");
          }
        else
          {
            printf(" ");
          }
      }

    printf("\n");

    /* Tens digit scale */

    printf("[detect] ");
    for (i = 0; i < DETECT_SAMPLES_X; i++)
      {
        if ((i % 10) == 0)
          {
            printf("%d", i / 10);
          }
        else
          {
            printf(" ");
          }
      }

    printf("\n");

    printf("[detect] 0         1         2         3"
           "         4         5         6         7\n");
    printf("[detect] 01234567890123456789012345678901234"
           "567890123456789012345678901234567890123456789\n");
  }

  /* Numerical summary */

  printf("\n");
  printf("[detect] peak=%d  blob=[%d..%d]  width=%d  "
         "cx=%.1f  conf=%.1f%%\n",
         peak_col, blob_l, blob_r, blob_width,
         (float)blob_weighted_sum / (float)blob_hits,
         confidence);
  printf("[detect] hits=%lu/%lu\n",
         (unsigned long)blob_hits,
         (unsigned long)total_samples);
  printf("[detect] dx=%+d  (%s)\n",
         dx, dx < -10 ? "LEFT" : dx > 10 ? "RIGHT" : "CENTER");

  return 0;

cleanup_irq:
  dvp_irq_detach();
cleanup_ctrl:
  dvp_ctrl_deconfig();
  return ret;
}

